firmware:
const int BTN = 4;
const int LED = 2;
int last = HIGH;
bool on = false;

void setup() {
  Serial.begin(115200);
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  digitalWrite(LED, LOW);
}

void loop() {
  int now = digitalRead(BTN);
  if (last == HIGH && now == LOW) {
    delay(30);
    if (digitalRead(BTN) == LOW) {
      on = !on;
      digitalWrite(LED, on ? HIGH : LOW);
      Serial.println(on ? "LED=ON" : "LED=OFF");
    }
  }
  last = now;
  delay(5);
}
